// Supabase Edge Function `email-worker`: drains one batch of the
// outbound_emails outbox per invocation (docs/supabase-native-architecture.md).
// `dist/` is generated by `pnpm --filter api build:edge`.
// pg_cron calls it every minute; request paths that queue mail can kick it
// right away; it kicks itself while batches come back full.
import { ASSET_ROOT, installAssetFs } from '../_shared/asset-fs.ts';
import { serveWorker } from '../_shared/worker-server.ts';
import assets from './dist/assets.mjs';

installAssetFs(assets as Record<string, string>);
(globalThis as { __SEALD_ASSET_DIR?: string }).__SEALD_ASSET_DIR = ASSET_ROOT;

const { createEmailWorker } = await import('./dist/edge.mjs');

type Batch = { claimed: number; batchSize: number };
type EmailWorker = { flushBatch(): Promise<Batch> };

serveWorker<EmailWorker, Batch>({
  name: 'email-worker',
  create: createEmailWorker as () => EmailWorker,
  run: (worker) => worker.flushBatch(),
  more: (batch) => batch.claimed >= batch.batchSize,
});
